import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { settingsKey, settingsPath, useSettings } from './settings';
import type { SettingKey, Settings as SheetSettings } from './settings';

// The sheet's settings: each value in force, and a form that changes it. The clerk limit is the most due
// a clerk may settle (two decimals); blank means no limit. The floor is the least a claim's live due is (two
// decimals); blank takes its default, 1.00. The terms are the whole days after its date by which a claim is due;
// blank takes its default, 14. The late percent (two decimals) is charged on an overdue claim's figure for every
// full 30 days it is overdue; blank takes its default, 0.00. A claim dated before the policy date rounds half up, on
// or after it half to even; blank makes it the sheet's today. While the sheet's today is on or after the period
// numbering from-date, a claim opened is numbered within its period; blank turns that off. Saving sends each setting whose field was changed; with none changed it
// sends the clerk limit, so saving a blank form clears the limit.
function Settings({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data } = useSettings(sheet);
  const [clerkLimit, setClerkLimit] = useState('');
  const [floor, setFloor] = useState('');
  const [terms, setTerms] = useState('');
  const [latePct, setLatePct] = useState('');
  const [policyDate, setPolicyDate] = useState('');
  const [periodNumberingFrom, setPeriodNumberingFrom] = useState('');
  const [changed, setChanged] = useState<SettingKey[]>([]);

  const save = useMutation({
    mutationFn: async (bodies: { key: SettingKey; value: string }[]) => {
      let updated: SheetSettings | undefined;
      for (const body of bodies) {
        updated = await postJson<SheetSettings>(byUser(settingsPath(sheet), user), body);
        queryClient.setQueryData(settingsKey(sheet), updated);
      }
      return updated;
    },
    onSuccess: () => {
      setClerkLimit('');
      setFloor('');
      setTerms('');
      setLatePct('');
      setPolicyDate('');
      setPeriodNumberingFrom('');
      setChanged([]);
    },
  });
  const send = useSubmitOnce(save);

  const touch = (key: SettingKey) => {
    setChanged((keys) => (keys.includes(key) ? keys : [...keys, key]));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a value that is not 0.00 or more with up to two decimals.
    const values: Record<SettingKey, string> = { 'clerk-limit': clerkLimit, floor, terms, 'late-pct': latePct, 'policy-date': policyDate,
      'period-numbering-from': periodNumberingFrom };
    const keys: SettingKey[] = changed.length === 0 ? ['clerk-limit'] : changed;
    send(keys.map((key) => ({ key, value: values[key] })));
  };

  return (
    <section>
      <h2>Settings</h2>
      <form onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="0.00 (blank: no limit)"
            value={clerkLimit}
            onChange={(e) => {
              setClerkLimit(e.target.value);
              touch('clerk-limit');
            }}
          />
        </label>{' '}
        now <span data-testid="setting-clerk-limit-current">{data?.clerkLimit ?? ''}</span>{' '}
        <label>
          Floor{' '}
          <input
            data-testid="setting-floor"
            placeholder="0.00 (blank: 1.00)"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              touch('floor');
            }}
          />
        </label>{' '}
        now <span data-testid="setting-floor-current">{data?.floor ?? ''}</span>{' '}
        <label>
          Terms (days){' '}
          <input
            data-testid="setting-terms"
            placeholder="days (blank: 14)"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              touch('terms');
            }}
          />
        </label>{' '}
        now <span data-testid="setting-terms-current">{data?.terms ?? ''}</span>{' '}
        <label>
          Late percent{' '}
          <input
            data-testid="setting-late-pct"
            placeholder="0.00 (blank: 0.00)"
            value={latePct}
            onChange={(e) => {
              setLatePct(e.target.value);
              touch('late-pct');
            }}
          />
        </label>{' '}
        now <span data-testid="setting-late-pct-current">{data?.latePct ?? ''}</span>{' '}
        <label>
          Policy date{' '}
          <input
            data-testid="setting-policy-date"
            placeholder="yyyy-mm-dd (blank: today)"
            value={policyDate}
            onChange={(e) => {
              setPolicyDate(e.target.value);
              touch('policy-date');
            }}
            // Clearing an already blank field fires no change, yet blanking the policy date must still be sent:
            // taking the field up counts as changing it.
            onFocus={() => touch('policy-date')}
          />
        </label>{' '}
        now <span data-testid="setting-policy-date-current">{data?.policyDate ?? ''}</span>{' '}
        <label>
          Period numbering from{' '}
          <input
            data-testid="setting-period-numbering-from"
            placeholder="yyyy-mm-dd (blank: off)"
            value={periodNumberingFrom}
            onChange={(e) => {
              setPeriodNumberingFrom(e.target.value);
              touch('period-numbering-from');
            }}
            // As the policy date: clearing an already blank field must still send the blank.
            onFocus={() => touch('period-numbering-from')}
          />
        </label>{' '}
        now <span data-testid="setting-period-numbering-from-current">{data?.periodNumberingFrom ?? ''}</span>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error" role="alert">
            {' '}The clerk limit, the floor and the late percent must be 0.00 or more with up to two decimals, the terms a whole number of days, the policy date and the period numbering from-date dates, or blank.
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 6, Component: Settings });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { hundredths } from '../rates/rates';

/** The sheet's settings: the clerk limit with two decimals, the most due a clerk may settle ('' for no limit);
 *  the floor with two decimals, the least a claim's live due is; and the terms, the whole days after its date by
 *  which a claim is due; and the late percent with two decimals, charged on an overdue claim's figure for every
 *  full 30 days it is overdue; and the policy date (yyyy-MM-dd; '' for the sheet's today): a claim dated before it
 *  rounds half up, on or after it half to even; and the period numbering from-date (yyyy-MM-dd; '' for off): while
 *  the sheet's today is on or after it, a claim opened is numbered within its period. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string };

/** A setting's key as the server names it, with the field of {@link Settings} that shows it. */
export type SettingKey = 'clerk-limit' | 'floor' | 'terms' | 'late-pct' | 'policy-date' | 'period-numbering-from';

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The terms a sheet starts with. */
export const DEFAULT_TERMS = '14';

export const settingsKey = (sheet: string) => ['settings', sheet] as const;

export const settingsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/settings`;

export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(settingsPath(sheet)),
  });
}

/** The sheet's floor in hundredths: the least a claim's live due is. */
export function useFloorCents(sheet: string): bigint {
  const { data } = useSettings(sheet);
  return hundredths(data?.floor ?? DEFAULT_FLOOR);
}

/** The sheet's terms: the whole days after its date by which a claim is due. */
export function useTerms(sheet: string): number {
  const { data } = useSettings(sheet);
  return Number(data?.terms ?? DEFAULT_TERMS);
}

/** The sheet's late percent in hundredths: charged on an overdue claim's figure for every full 30 days it is
 *  overdue. */
export function useLatePctCents(sheet: string): bigint {
  const { data } = useSettings(sheet);
  return hundredths(data?.latePct ?? DEFAULT_LATE_PCT);
}

/** The sheet's policy date (yyyy-MM-dd), or '' when it is the sheet's today. */
export function usePolicyDate(sheet: string): string {
  const { data } = useSettings(sheet);
  return data?.policyDate ?? '';
}

